          "briefTitle": "The Use of Probiotics in Patients With Symptomatic Oral Lichen Planus",
          "officialTitle": "The Use of Probiotics in Patients With Symptomatic Oral Lichen Planus"
        },
        "statusModule": {
          "statusVerifiedDate": "2015-12",
          "overallStatus": "COMPLETED",
