        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Mette Kirstine Keller",
            "investigatorTitle": "Assistant professor",
            "investigatorAffiliation": "University of Copenhagen"
          },
