          },
          "briefTitle": "Effect of Adjunctive Systemic Vitamin E on Clinical Parameters and Salivary Total Antioxidant Capacity in Symptomatic Oral Lichen Planus Patients: Randomized-controlled Clinical Trial",
          "officialTitle": "Evaluation of Salivary Total Oxidant Capacity in Oral Lichen Planus Patients Before and After Treatment With Topical Corticosteroid Supplemented With Vitamin E Versus Topical Corticosteroid Alone"
        },
        "statusModule": {
          "statusVerifiedDate": "2019-10",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2016-01-22",
            "type": "ACTUAL"
          },
          "primaryCompletionDateStruct": {
