            "maskingInfo": {
              "masking": "DOUBLE",
              "maskingDescription": "Randomization: The enrolled subjects were randomly assigned to one of two treatment protocols using a computer-generated table. This method ensures impartial allocation and avoids biases in treatment selection for each patient.\n\nMasking: Medications were prepared and packaged in identical, sealed, and numbered envelopes by the hospital pharmacy and a clinician not involved in the subsequent phases of the study. Each sealed envelope contained the protocol assignment for individual patients and written instructions for the application of the medications. Moreover, clinicians involved in treatment evaluation at each follow-up session were blinded to the treatment assigned to each patient.",
              "whoMasked": [
                "PARTICIPANT",
                "INVESTIGATOR"
              ]
            }
          },
