          },
          "briefTitle": "Off-Label Use of Ribavirin in Management of Mucocutaneous Extrahepatic Manifestations of HCV Infection",
          "officialTitle": "Randomized Controlled Study of Off-Label Use of Ribavirin in Management of Mucocutaneous Extrahepatic Manifestations of HCV Infection"
        },
