          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "This study is a randomized, double-blind, sham-controlled, parallel-group trial. Participants will be randomly allocated to either an active bilateral cerebellar transcranial direct current stimulation (ctDCS) group or a sham stimulation group in a 1:1 ratio. The parallel design allows for direct comparison of outcomes between groups to evaluate the efficacy of bilateral cerebellar neuromodulation in individuals with multiple sclerosis.",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "TRIPLE",
              "maskingDescription": "This study will employ a double-blind design with additional blinding of outcome assessors. Participants and care providers administering the stimulation will be blinded to group allocation through the use of identical stimulation procedures in both active and sham conditions. The tDCS device will be pre-programmed to deliver either active or sham stimulation, ensuring allocation concealment. Investigators involved in data analysis and outcome assessors conducting clinical evaluations will remain blinded to group assignment throughout the study to minimize bias.",
              "whoMasked": [
                "PARTICIPANT",
                "CARE_PROVIDER",
                "OUTCOMES_ASSESSOR"
              ]
            }
          },
          "enrollmentInfo": {
