          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Sham Bilateral Cerebellar tDCS",
              "type": "SHAM_COMPARATOR",
              "description": "Participants in this arm will receive sham bilateral cerebellar transcranial direct current stimulation (ctDCS). Electrodes will be positioned identically to the active stimulation group (bilateral cerebellar montage). The device will deliver a brief ramp-up and ramp-down of current at the beginning and end of the session to mimic the sensation of active stimulation, but no continuous current will be applied. Each session will last 20 minutes, 5 sessions per week for 2 consecutive weeks (total of 10 sessions). This procedure is designed to maintain participant blinding.",
              "interventionNames": [
                "Device: Sham Bilateral Cerebellar tDCS"
              ]
            },
            {
              "label": "TDCS GROUP",
              "type": "EXPERIMENTAL",
              "description": "Participants in this arm will receive bilateral cerebellar transcranial direct current stimulation (ctDCS). Anodal electrodes will be positioned bilaterally over the cerebellar hemispheres (3 cm lateral to the inion), with reference electrodes placed over the buccinator muscles. Stimulation will be delivered at 2 mA for 20 minutes per session, 5 sessions per week for 2 consecutive weeks (total of 10 sessions). The intervention will be administered as a standalone neuromodulation protocol without concurrent task-oriented rehabilitation to isolate neuro-modulatory effects.",
              "interventionNames": [
                "Device: Bilateral Cerebellar Transcranial Direct Current Stimulation (ctDCS)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DEVICE",
              "name": "Bilateral Cerebellar Transcranial Direct Current Stimulation (ctDCS)",
              "description": "Bilateral cerebellar transcranial direct current stimulation (ctDCS) will be delivered using a constant-current stimulator. Anodal electrodes (5 × 5 cm; 25 cm²) will be positioned bilaterally over the cerebellar hemispheres (approximately 3 cm lateral to the inion), with reference electrodes placed over the buccinator muscles. Stimulation will be applied at 2 mA for 20 minutes per session. Participants will receive five sessions per week for two consecutive weeks (total of 10 sessions).",
              "armGroupLabels": [
                "TDCS GROUP"
              ],
              "otherNames": [
                "Cerebellar tDCS"
