            {
              "type": "DRUG",
              "name": "Levetiracetam",
              "description": "formulation: tablet or dry syrup\n\nstrength: 250 mg tablet, 500 mg tablet, dry syrup 50%\n\ndosage: Sb ≥16 years and ≥4 and \\<16 years (≥50 kg): 1000 mg/day, 2000 mg/day or 3000 mg/day; Sb ≥4 and \\<16 years (\\<50kg): 20 mg/kg/day, 40 mg/kg/day, or 60 mg/kg/day\n\nfrequency: twice daily",
              "armGroupLabels": [
                "Levetiracetam"
              ],
              "otherNames": [
