              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Incidence of Treatment Emergent Adverse Events During the Entire Study Period",
              "timeFrame": "Through study completion, an average of 3 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "The Percentage Change in Generalized Tonic-Clonic (GTC) Seizure Frequency Per Week Over the Evaluation Period From Either of the Combined Baseline Periods of the Previous Studies (N01159 or N01363).",
              "description": "Percentage change in generalized tonic-clonic (GTC) seizure frequency per week from Baseline of previous studies B over the Treatment Period A is calculated using the equation:\n\nPercentage change from Baseline = ((A-B)/B)\\*100. Percentage change from baseline is not defined for subjects whose baseline information is missing / unknown or equal to zero, or whose seizure frequency per week is missing/unknown. A negative value in change in generalized tonic-clonic (GTC) seizure frequency indicates a reduction of generalized tonic-clonic (GTC) seizure frequency over the Treatment Period.",
              "timeFrame": "During the Treatment Period (up to 4.8 years)"
            },
            {
              "measure": "The Incidence of Adverse Drug Reactions During the Entire Study Period",
              "description": "Adverse drug reactions excludes Adverse Events (AEs) described by the investigators with no relationship to study drug.",
              "timeFrame": "Through study completion, an average of 3 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* The subject in Japan has completed either of the studies N01159 or N01363 or has discontinued the N01159 study due to lack of efficacy.\n* The subject who is judged to benefit from continued treatment with Levetiracetam by the investigators\n\nExclusion Criteria:\n\n* Subjects with multiple protocol deviations during N01159 or N01363, such as missing laboratory data, and low or noncompliance with the study medication, and who the investigator considers not to have the potential to have deviations stopped are ineligible",
