        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Lacosamide + Low-Dose Levetiracetam",
              "type": "EXPERIMENTAL",
              "description": "Participants received lacosamide 50 mg twice a day for one week followed by 100 mg twice daily added to low dose levetiracetam ≤1500 mg/day (polytherapy) for 6 months in patients with breakthrough seizures on low-dose levetiracetam.",
              "interventionNames": [
                "Drug: lacosamide",
                "Drug: levetiracetam"
              ]
            },
            {
              "label": "Control Group (High-Dose Levetiracetam)",
