        "descriptionModule": {
          "briefSummary": "Sepsis-associated encephalopathy is associated with high mortality rates and long-term neuropsychiatric disorders. Currently, there is no specific treatment for sepsis-associated encephalopathy. Levetiracetam, a broad-spectrum antiepileptic widely used in intensive care units, has neuroprotective properties. We propose the KiSS study, a multicenter, prospective, randomized, double-blind trial with two arms, evaluating the effect of levetiracetam treatment for seven days during septic shock on the occurrence and duration of sepsis-associated encephalopathy."
        },
        "conditionsModule": {
          "conditions": [
            "Septic Shock"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE3"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "Phase III, multicenter, comparative, randomized, double-blind, placebo-controlled study",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "TRIPLE",
              "maskingDescription": "Double blind",
              "whoMasked": [
                "PARTICIPANT",
                "CARE_PROVIDER",
                "INVESTIGATOR"
              ]
            }
          },
