            },
            {
              "measure": "Occurrence of epileptic seizures",
              "description": "From Day 1 to Day 14 (confirmed by EEG or tonic-clonic seizures) and/or occurrence of epileptic abnormalities (periodic epileptic discharges)",
              "timeFrame": "Up to day 14"
            },
            {
              "measure": "Time between cessation of sedation and awakening",
              "description": "Defined by spontaneous eye opening, among patients not deceased under sedation",
              "timeFrame": "At day 90"
            },
            {
              "measure": "Severity of cognitive impairment",
              "description": "Evaluated by a telephone survey using Telephone MoCA (Montreal Cognitive Assessment). The scores ranges from 0 to 30.\n\nA score of 26 or higher is typically considered normal. A score of 25 or lower may indicate cognitive impairment, such as mild cognitive impairment (MCI) or early-stage dementia.",
              "timeFrame": "At day 90"
            },
            {
              "measure": "Severity of anxiety and depression",
              "description": "Assessed with HADS (Hospital Anxiety and Depression Scale) scale Score varies from 0 to 21 for each componant (Anxiety and depression) The higher the score, the more severe the anxiety or depression.",
              "timeFrame": "At day 90"
            },
            {
              "measure": "Presence of post-traumatic stress (PTSD)",
              "description": "Assessed by IES-R (Impact of Event Scale Revisited) The total score can range from 0 to 88. Higher scores indicate greater trauma-related distress and a higher likelihood of experiencing PTSD symptoms.",
              "timeFrame": "At day 90"
            },
            {
              "measure": "Quality of life scoring",
              "description": "Using EQ-5D-5L. It evaluates five dimensions : mobility, self-care, usual activities, pain/discomfort and anxiety/depression and each dimension has five levels : no problems, slight problems, moderate problems, severe problems and extreme problems. Answers are given on a 5-point scale by domain, the higher the score, the poorer the quality of life.",
              "timeFrame": "At day 90"
            },
            {
              "measure": "Autonomy in daily life",
              "description": "Using Katz Index of Independence in Activities of Daily Living (ADL) The score varies from 0 to 6, the lower the score, the more dependent the person.",
              "timeFrame": "At day 90"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion criteria :\n\n* Aged 18 years or older\n* Hospitalized in intensive care for less than 96 hours\n* Presenting with septic shock evolving for less than 24 hours defined by:\n\n  1. Clinically or microbiologically documented infection and\n  2. SOFA score ≥ 2 or an increase in SOFA score ≥ 2 points if organ dysfunction was present before the infection and\n  3. Need for vasopressor administration to maintain a mean arterial pressure ≥ 65mmHg and\n  4. Lactate level \\> 2mmol/L (18mg/dL) despite adequate fluid resuscitation\n* Patient's consent, their next of kin consent, or emergency inclusion\n\nNon inclusion criteria :\n\n* Chronic long-term antiepileptic treatment upon admission or patient with uncontrolled seizures\n* Chronic or progressive central neurological pathologies of traumatic, inflammatory, vascular, infectious, neoplastic, or degenerative origin, defined by cognitive impairments preventing independent living or an IQCODE score \\> 4.5\n* Patient with moderate to severe dementia\n* Patient with psychiatric history and/or suicide attempts\n* Severe head trauma within the past 3 months\n* Patients with limitations on active therapies or for whom therapeutic commitment is not maximal\n* Patient presenting a prolonged QTc interval on ECG and/or at risk of cardiovascular disease\n* Concomitant treatment with Methotrexate during the administration of the investigational treatment\n* Allergy to levetiracetam\n* Minor patients\n* Ongoing pregnancy (blood or urinary βHCG)\n* Breastfeeding women\n* Patients under guardianship or trusteeship\n* Non-affiliation with social security or CMU\n* Participation in another interventional trial with a drug that may interact with levetiracetam or may impact the evaluation of KiSS trial outcomes. In case of doubt, please contact the trial's coordinating investigator.",
          "healthyVolunteers": false,
