        "descriptionModule": {
          "briefSummary": "Hypovitaminosis D is highly prevalent in people with lung cancer, and may have adverse clinical consequences. The long and variable pharmacokinetic half-life of vitamin D makes prompt vitamin D replacement problematic. This is an open, one-armed therapeutic intervention using a loading dose of vitamin D that will be predicted to increase plasma 25-hydroxyvitamin D concentrations of every patient well into the normal range (\\> 100 nmol/L) within 2 or 3 weeks and monitored after 2 and 3 weeks of loading and maintenance dose. Preliminary data will also be obtained to identify potentially clinical important outcome benefits for future investigation. The outcomes are\n\n1. plasma 25OHD concentration\n2. Vitamin D binding protein and other plasma concentrations\n3. Mood and symptom"
        },
        "conditionsModule": {
          "conditions": [
            "Lung Cancer"
          ],
          "keywords": [
            "Lung cancer",
            "vitamin D",
            "pharmacokinetics"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 80,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Vitamin D",
              "type": "EXPERIMENTAL",
              "description": "vitamin D 20,000 IU per day for 2 weeks followed by 10,000 IU per day for a further 7 days",
              "interventionNames": [
                "Dietary Supplement: vitamin D"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "vitamin D",
              "description": "vitamin D3 20,000 IU per day for 14 days followed by 10,000 IU per day for a further 7 days",
              "armGroupLabels": [
                "Vitamin D"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Plasma 25-hydroxyvitamin D concentration",
              "description": "Plasma 25OHD concentration measured within 24 h prior to commencing vitamin D therapy, and again after 14 and 21 days of continuous vitamin D therapy",
              "timeFrame": "3 weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Mood",
              "description": "Two validated brief mood assessment questionnaires measured\n\n1. On two occasions (one week apart) at baseline prior to staring therapy\n2. After 2 weeks of therapy\n3. After 3 weeks of therapy",
              "timeFrame": "3 weeks"
            },
            {
              "measure": "Symptoms",
              "description": "As with mood questionnaire, a symptom questionnaire (Edmonton Symptom Assessment System) will be administered two times (one week apart) prior to starting vitamin therapy and after 14 and 21 days of continuous vitamin D administration",
              "timeFrame": "3 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Any patient with advanced lung cancer whether or not receiving specific anti-cancer therapy\n2. Mentally competent (but need not be fluent in French or English if capable neutral translator available)\n3. Self report of reduced food intake and/or involuntary weight loss of any extent at time of enrollment: does not have to be documented\n\nExclusion Criteria:\n\n1. Current diagnosis of primary hyperparathyroidism\n2. Nephrocalcinosis\n3. Current or suspected active tuberculosis, histoplasmosis, sarcoidosis, or other granulomatous disease\n4. Current using a vitamin D supplement providing \\> 1000 IU/day\n5. Current prescribed calcitriol in any dose\n6. History of extensive sunlight exposure (\\> 30 min summer sunlight exposure per day for more than 5 days per week) in previous 3 months\n7. Expected to die within next 2 months\n8. Pregnancy",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
