          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "The primary objective of the study is to determine the maximum tolerated dose (MTD) and the recommended dose (RD) of the combination intravenous Cetuximab/oral Gefitinib."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "To determine the pharmacokinetic (PK) parameters of the combination Cetuximab/Gefitinib"
            },
            {
              "measure": "To determine the pharmacogenomic profile of study patients and to correlate the different profiles with efficacy"
            },
            {
              "measure": "To determine the possible correlation between activity and the polymorphisms of the EGFR measured in the blood and in the primary tumour"
            },
            {
              "measure": "To assess the possible immune response related to cetuximab"
            },
            {
              "measure": "To estimate signs of clinical activity (response rate according to the RECIST criteria)"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Written informed consent prior to inclusion\n* Confirmed histological diagnosis of non-resectable, solid, malignant, EGFR expressing tumours of the following types: colorectal cancer, head and neck cancer and non-small cell lung cancer (NSCLC). Advanced clinical stage III/IV which did not respond to standard therapy or for which no suitable therapy exists\n* Patients with at least one evaluable lesion (evaluable disease) by the RECIST criteria\n* Availability of tumour tissue, whether from primary tumour or metastasis to determine EGFR expression\n* Viability of establishing outpatient treatment\n* Effective contraception for patients of both sexes if there is a risk of conception\n* Karnofsky performance status greater than 70 %\n* Life expectancy \\> 12 weeks\n* Adequate renal function (creatinine \\< 1.5 x UNL), liver function (bilirubin \\< 1.5 x UNL, ALT/AST \\< 2.5 x UNL o \\<5 x UNL if hepatic metastasis) and adequate bone marrow (leucocytes \\> 3000/µl, absolute neutrophil count \\> 1500/µl, platelets \\> 100,000/µl, haemoglobin \\> 9 g/dl)\n* Patients must not have undergone chemotherapy, radiotherapy or major surgery during the 3 weeks before the beginning of the study, and they must have recovered from the relevant secondary effects of previous treatments\n* Patients agree to have a new biopsy after two weeks.\n\nExclusion Criteria:\n\n* Patients with any symptom of bowel obstruction and/or inflammatory bowel disease\n* Previous therapy with anti-EGFR drugs\n* Patients with known cerebral metastasis\n* Patients with known active and uncontrolled infections\n* Severe uncontrolled organic dysfunctions or metabolic disorders\n* Patients unable to give informed consent\n* Patients who do not wish to or who cannot undergo the specific study treatments and the study procedures\n* Pregnancy or breastfeeding\n* Patient participation in another clinical trial during the previous 30 days\n* Patients with known drug and/or alcohol abuse\n* Known hypersensitivity to chimeric MoAbs or pretreatment with MoAbs\n* Any other malignant tumour in the last two years or previously diagnosed malignant tumour if there is no guarantee that it is under complete control, except for suitably treated in situ cervical carcinoma or basocellular carcinoma\n* Known severe hypersensitivity to ZD1839 or any of the excipients of this product\n* Any evidence of clinically active interstitial lung disease (patients with chronic, stable, radiographic changes who are asymptomatic need not to be excluded)\n* Any unresolved chronic toxicity greater than common toxicity criteria (CTC) grade 2 from previous anticancer therapy\n* Concomitant use of phenytoin, carbamazepine, rifampicin, barbiturates, or St John's Wort",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
