          "briefTitle": "Active Videogames Against Obesity in Children",
          "officialTitle": "Active Video Games Against Obesity and Sedentarism in Children Between 9 and 11 Years Old: a Disruptive Proposal",
          "acronym": "VIDEOACTIVO"
        },
        "statusModule": {
          "statusVerifiedDate": "2024-01",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
