        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "José A. Casajús",
            "investigatorTitle": "Professor",
            "investigatorAffiliation": "Universidad de Zaragoza"
          },
          "leadSponsor": {
