        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Allan Linneberg",
            "investigatorTitle": "Researchmanager",
            "investigatorAffiliation": "Glostrup University Hospital, Copenhagen"
          },
          "leadSponsor": {
