        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Carmen Daniela Quero Calero",
            "investigatorTitle": "Professor, principal investigator",
            "investigatorAffiliation": "Catholic University of Murcia"
          },
          "leadSponsor": {
