          },
          "briefTitle": "Long Distance Running Training by Older Adults",
          "officialTitle": "Effects of Long Distance Running Training on the Posture and Movement Control of Sedentary Older Adults"
        },
        "statusModule": {
          "statusVerifiedDate": "2011-11",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2012-01"
          },
          "primaryCompletionDateStruct": {
