          "conditions": [
            "Physical Activity",
            "Aging"
          ],
          "keywords": [
            "biomechanics",
            "motor control",
            "movement",
            "walking",
            "running",
            "sedentarism",
            "joint moment"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
