        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change from baseline of posture and movement patterns at 16 weeks",
              "description": "biomechanical and physiological measures of the posture and movement patterns",
              "timeFrame": "Two weeks before and two weeks after the training for sixteen months"
            }
          ],
          "secondaryOutcomes": [
            {
